/* ===== module: sync-adapter.js ===== */
    /** Supabase client/transport adapter for the sync system (split from sync.js, #99 B15).
     *
     *  The client is lazily created via dynamic import() of the CDN build inside
     *  this classic script — if the CDN is unreachable the app degrades
     *  silently to signed-out local-only behavior. The session persists in
     *  localStorage and magic-link redirects are detected by default.
     *  (The publishable key ships in the app by design.)
     */
     /* Module map (v1.006) — Key: getSupabase(), signedInUser(), isNetworkError(), resetSupabaseUnavailable(). Depends on: the Supabase CDN build (dynamic import); degrades to local-only offline. */
/* #99 C4: the sync files share one namespace pattern, explained here once.
   No ES modules are used (plain <script> tags): each sync file wraps its whole
   body in an immediately-invoked function `(function(){ ... })()` (IIFE) so its
   internals stay private to the file; its public API is attached to the shared
   `window.Sync` object (`var Sync = window.Sync = window.Sync || {}` merges the
   contributions of the four sync files into one object). A few bare-global
   forwarding functions at the bottom of each file (e.g. markSyncDirty) exist
   only so older call sites keep working unchanged. */
    var Sync = window.Sync = window.Sync || {};
    (function(){
      'use strict';
      const SUPABASE_URL='https://kbiikscyyiedgzijamnu.supabase.co';
      const SUPABASE_PUBLISHABLE_KEY='sb_publishable_OcWd1Wt0WKMtMpI3jBIGUg_kJ4kJ3wn';

      let supabaseClient=null, supabasePromise=null, supabaseUnavailable=false;
      /* PPL fix batch (2026-10-28, B9e): WHY the client is unavailable,
         so the status line can name the real failure. 'load' = the CDN
         import itself failed (the device may be perfectly online — a
         blocked CDN printed "Sync unavailable offline" before this);
         null = no failure recorded. */
      let supabaseFailureKind=null;

      /** Lazily import the Supabase client. Dynamic import in try/catch so an
          unreachable CDN (offline / blocked) leaves the app fully working.
          Single-flighted (2026-09-13): boot fires many concurrent
          getSupabase() callers (sync init + share-link resolve); without the
          shared promise each one created its own client and GoTrue warned
          about multiple instances under the same storage key (#228). */
      async function getSupabase(){
        if(supabaseClient)return supabaseClient;
        if(supabaseUnavailable)return null;
        if(supabasePromise)return supabasePromise;
        supabasePromise=(async()=>{
          try{
            const mod=await import('https://esm.sh/@supabase/supabase-js@2');
            supabaseClient=mod.createClient(SUPABASE_URL,SUPABASE_PUBLISHABLE_KEY);
            supabaseFailureKind=null;
            return supabaseClient;
          }catch(err){supabaseUnavailable=true;supabaseFailureKind='load';return null;}
          finally{supabasePromise=null;}
        })();
        return supabasePromise;
      }
      /* Re-arms the Supabase CDN import after a failure (so 'online' can retry). */
      function resetSupabaseUnavailable(){supabaseUnavailable=false;supabaseFailureKind=null;}
      /* B9e (2026-10-28): the recorded client failure kind ('load' when
         the CDN import failed), or null. Lets resumeSync word the
         status for the failure that actually happened. */
      function supabaseFailure(){return supabaseFailureKind;}
      /* The current Supabase session user, or null when signed out/unreachable. */
      async function signedInUser(){
        const sb=await getSupabase();
        if(!sb)return null;
        try{const {data}=await sb.auth.getSession();return data&&data.session&&data.session.user?data.session.user:null;}
        catch(_){return null;}
      }
      /* #70: Safari reports failed fetches as TypeError "Load failed" — a
         cryptic dead end. Translate network-type failures into something
         actionable everywhere sync/auth touches the network. */
      function isNetworkError(err){
        if(typeof navigator!=='undefined'&&navigator&&navigator.onLine===false)return true;
        const m=String((err&&(err.message||err))||'').toLowerCase();
        return /load failed|failed to fetch|network error|network request failed|fetch failed|econn|etimedout|enotfound|socket/.test(m);
      }

      Sync.getSupabase=getSupabase;
      Sync.resetSupabaseUnavailable=resetSupabaseUnavailable;
      Sync.supabaseFailure=supabaseFailure;
      Sync.signedInUser=signedInUser;
      Sync.isNetworkError=isNetworkError;
    })();
    /* The bare-global getSupabase()/signedInUser() forwarding shims were
       removed in the v1.912 #99 cleanup — their last call sites were the
       parked onboarding gate (deleted #99 B1); all callers use Sync.*. */
